namespace Itacr.Application.Orders.CreateOrder;

public sealed record CreateOrderItem(Guid ProductId, int Quantity);

/// <summary>
/// An order taken by a waiter. <paramref name="ClientOrderId"/> is generated by the device and identifies the order
/// across retries; prices are never part of the request, they come from the menu. <paramref name="CreatedAt"/> is when
/// the waiter sent it on the device, which is earlier than now for an order that waited offline; without it the order
/// is created now.
/// </summary>
public sealed record CreateOrderCommand(
    Guid ClientOrderId,
    Guid? TableId,
    bool TakeAway,
    IReadOnlyList<CreateOrderItem> Items,
    DateTimeOffset? CreatedAt = null);
